/**
 * run-image-benchmark.js
 * ========================
 * Tests the fine-tuned vision model's ability to:
 *   1. Transcribe handwritten student work from an image
 *   2. Grade it correctly against the rubric
 *
 * Reads:  test-data/image-benchmark-cases.json  (generated by gen-handwriting-images.py)
 * Needs:  PNG files in test-data/handwriting-images/
 * Calls:  Ollama /api/chat directly (no O.G.R.E. server required)
 *
 * USAGE:
 *   bun run test-data/run-image-benchmark.js
 *   bun run test-data/run-image-benchmark.js --model=qwen3.5-9B-stat-grader:latest
 *   bun run test-data/run-image-benchmark.js --quality=bad        # only bad handwriting
 *   bun run test-data/run-image-benchmark.js --quality=good,medium
 *
 * OPTIONS:
 *   --model=<name>      Ollama model to test (default: qwen3.5-9B-stat-grader:latest)
 *   --quality=<list>    Comma-separated quality filter: good, medium, bad (default: all)
 *   --tolerance=<n>     Score agreement tolerance in points (default: 1)
 *   --ollamaUrl=<url>   Ollama base URL (default: http://localhost:11434)
 *   --timeout=<ms>      Per-request timeout in ms (default: 120000)
 *   --output=<path>     Save results JSON to path (default: test-data/image-benchmark-results.json)
 */

const fs   = await import('fs');
const path = await import('path');

// ── Config ────────────────────────────────────────────────────────────────────

const CONFIG = {
  model:      'qwen3.5-9B-stat-grader:latest',
  quality:    null,    // null = all; or ['good','medium','bad'] subset
  tolerance:  1,
  ollamaUrl:  'http://localhost:11434',
  timeoutMs:  120_000,
  casesFile:  'test-data/image-benchmark-cases.json',
  outputFile: 'test-data/image-benchmark-results.json',
  reportFile: 'test-data/image-benchmark-report.md',
};

// CLI argument parsing
for (const arg of process.argv.slice(2)) {
  const [k, v] = arg.replace(/^--/, '').split('=');
  if (k === 'model')      CONFIG.model      = v;
  if (k === 'quality')    CONFIG.quality    = v.split(',');
  if (k === 'tolerance')  CONFIG.tolerance  = parseFloat(v);
  if (k === 'ollamaUrl')  CONFIG.ollamaUrl  = v;
  if (k === 'timeout')    CONFIG.timeoutMs  = parseInt(v);
  if (k === 'output')     CONFIG.outputFile = v;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

const sleep = (ms) => new Promise(r => setTimeout(r, ms));

/** Read a PNG file and return base64 string (no data-URI prefix). */
function imageToBase64(filePath) {
  const buf = fs.readFileSync(filePath);
  return buf.toString('base64');
}

/** Compute Levenshtein edit distance between two strings (case-insensitive). */
function editDistance(a, b) {
  a = a.toLowerCase().trim();
  b = b.toLowerCase().trim();
  const m = a.length, n = b.length;
  const dp = Array.from({ length: m + 1 }, (_, i) =>
    Array.from({ length: n + 1 }, (_, j) => (i === 0 ? j : j === 0 ? i : 0))
  );
  for (let i = 1; i <= m; i++)
    for (let j = 1; j <= n; j++)
      dp[i][j] = a[i-1] === b[j-1]
        ? dp[i-1][j-1]
        : 1 + Math.min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]);
  return dp[m][n];
}

/** Similarity ratio: 1.0 = identical, 0.0 = completely different. */
function similarity(a, b) {
  const maxLen = Math.max(a.length, b.length);
  if (maxLen === 0) return 1.0;
  return 1 - editDistance(a, b) / maxLen;
}

// ── Grading call ──────────────────────────────────────────────────────────────

async function gradeImage(b64Image, rubricPrompt) {
  const SYSTEM = (
    'You are an expert grading assistant. '
    + 'If the student\'s work is provided as an image, transcribe it verbatim before grading. '
    + 'Then grade against the provided rubric. Output: JSON object only.'
  );

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), CONFIG.timeoutMs);

  try {
    const res = await fetch(`${CONFIG.ollamaUrl}/api/chat`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: CONFIG.model,
        messages: [
          { role: 'system',  content: SYSTEM },
          {
            role: 'user',
            content: rubricPrompt,
            images: [b64Image],   // Ollama vision format
          },
        ],
        stream: false,
        options: { temperature: 0 },
      }),
      signal: controller.signal,
    });

    if (!res.ok) {
      const txt = await res.text();
      throw new Error(`Ollama HTTP ${res.status}: ${txt.slice(0, 200)}`);
    }

    const data = await res.json();
    const rawContent = data?.message?.content ?? '';

    // Extract JSON from response (model may wrap in markdown fences)
    const jsonMatch = rawContent.match(/\{[\s\S]*\}/);
    if (!jsonMatch) throw new Error(`No JSON in response: ${rawContent.slice(0, 200)}`);

    const parsed = JSON.parse(jsonMatch[0]);
    return {
      transcription: parsed.transcription ?? '',
      score: parsed.score ?? null,
      rawContent,
    };
  } finally {
    clearTimeout(timer);
  }
}

// ── Main ──────────────────────────────────────────────────────────────────────

console.log('O.G.R.E. Image Benchmark');
console.log('========================');
console.log(`Model:     ${CONFIG.model}`);
console.log(`Tolerance: ±${CONFIG.tolerance} point(s)`);
console.log(`Ollama:    ${CONFIG.ollamaUrl}`);
if (CONFIG.quality) console.log(`Quality:   ${CONFIG.quality.join(', ')}`);
console.log();

// 1. Load cases
const cases = JSON.parse(fs.readFileSync(CONFIG.casesFile, 'utf-8')).cases;
const filtered = CONFIG.quality
  ? cases.filter(c => CONFIG.quality.includes(c.handwritingQuality))
  : cases;

console.log(`Running ${filtered.length} / ${cases.length} cases...\n`);

// 2. Preflight: check Ollama is up and model exists
try {
  const hRes = await fetch(`${CONFIG.ollamaUrl}/api/tags`);
  if (!hRes.ok) throw new Error(`status ${hRes.status}`);
  const tags = await hRes.json();
  const modelNames = (tags.models ?? []).map(m => m.name);
  const modelFound = modelNames.some(n => n === CONFIG.model || n.startsWith(CONFIG.model.replace(':latest', '')));
  if (!modelFound) {
    console.warn(`WARNING: Model "${CONFIG.model}" not found in Ollama. Available: ${modelNames.slice(0,5).join(', ')}`);
    console.warn('Run:  ollama create qwen3.5-9B-stat-grader -f fine-tuned-model/Modelfile-qwen3.5-9B-stat-grader\n');
  } else {
    console.log(`[preflight] Model found: ${CONFIG.model}`);
  }
} catch (err) {
  console.error(`[preflight] Ollama not reachable at ${CONFIG.ollamaUrl}: ${err.message}`);
  process.exit(1);
}

// 3. Run each case
const results = [];
let scoreAgree = 0, transcribeWell = 0, bothPass = 0;

for (let i = 0; i < filtered.length; i++) {
  const c = filtered[i];
  const imgPath = path.join('test-data', c.imageFile.replace(/^.*handwriting-images\//, 'handwriting-images/'));

  process.stdout.write(`[${i+1}/${filtered.length}] ${c.id} (score=${c.groundTruthScore}, ${c.handwritingQuality})... `);

  let result = {
    id: c.id,
    handwritingQuality: c.handwritingQuality,
    transcriptionFidelity: c.transcriptionFidelity,
    expectedScore: c.groundTruthScore,
    modelScore: null,
    modelTranscription: null,
    scorePass: false,
    transcriptionSimilarity: 0,
    transcriptionPass: false,
    bothPass: false,
    error: null,
  };

  try {
    const b64 = imageToBase64(imgPath);
    const gradeResult = await gradeImage(b64, c.rubricPrompt);

    const modelScore = typeof gradeResult.score === 'number' ? gradeResult.score : null;
    const modelTranscription = gradeResult.transcription ?? '';

    // Score check: within tolerance of expected
    const scorePass = modelScore !== null && Math.abs(modelScore - c.groundTruthScore) <= CONFIG.tolerance;

    // Transcription check: compare to both exact and acceptable versions
    const simExact      = similarity(modelTranscription, c.exactTranscription);
    const simAcceptable = similarity(modelTranscription, c.acceptableTranscription);
    const transcriptionSim = Math.max(simExact, simAcceptable);
    const transcriptionPass = transcriptionSim >= 0.70;  // 70% similarity threshold

    result = {
      ...result,
      modelScore,
      modelTranscription,
      scorePass,
      transcriptionSimilarity: Math.round(transcriptionSim * 100),
      transcriptionPass,
      bothPass: scorePass && transcriptionPass,
    };

    if (scorePass) scoreAgree++;
    if (transcriptionPass) transcribeWell++;
    if (scorePass && transcriptionPass) bothPass++;

    const scoreTag = scorePass ? '✓' : `✗(got ${modelScore})`;
    const transTag = transcriptionPass ? `✓(${result.transcriptionSimilarity}%)` : `✗(${result.transcriptionSimilarity}%)`;
    console.log(`score:${scoreTag}  transcription:${transTag}`);

  } catch (err) {
    result.error = err.message;
    console.log(`ERROR: ${err.message.slice(0, 80)}`);
  }

  results.push(result);

  // Small delay between calls to avoid overwhelming Ollama
  if (i < filtered.length - 1) await sleep(500);
}

// 4. Summary
const n = filtered.length;
const scorePct      = Math.round(scoreAgree / n * 100);
const transcribePct = Math.round(transcribeWell / n * 100);
const bothPct       = Math.round(bothPass / n * 100);

console.log('\n════════════════════════════════');
console.log(`Cases run:              ${n}`);
console.log(`Score agreement (±${CONFIG.tolerance}): ${scoreAgree}/${n} = ${scorePct}%`);
console.log(`Transcription (≥70%):   ${transcribeWell}/${n} = ${transcribePct}%`);
console.log(`Both pass:              ${bothPass}/${n} = ${bothPct}%`);

// By quality level
for (const q of ['good', 'medium', 'bad']) {
  const qResults = results.filter(r => r.handwritingQuality === q);
  if (!qResults.length) continue;
  const qScore = qResults.filter(r => r.scorePass).length;
  const qTrans = qResults.filter(r => r.transcriptionPass).length;
  const qN     = qResults.length;
  console.log(`  ${q.padEnd(8)}: score ${qScore}/${qN}  transcription ${qTrans}/${qN}`);
}

// 5. Save results JSON
const output = {
  timestamp: new Date().toISOString(),
  config: { model: CONFIG.model, tolerance: CONFIG.tolerance },
  summary: {
    total: n,
    scoreAgreementPct: scorePct,
    transcriptionPct:  transcribePct,
    bothPassPct:       bothPct,
  },
  results,
};
fs.writeFileSync(CONFIG.outputFile, JSON.stringify(output, null, 2));
console.log(`\nResults saved: ${CONFIG.outputFile}`);

// 6. Write markdown report
const md = `# O.G.R.E. Image Benchmark Report
Model: \`${CONFIG.model}\`  
Run: ${new Date().toISOString().slice(0, 19).replace('T', ' ')}  
Cases: ${n}  

## Summary

| Metric | Score |
|---|---|
| Score agreement (±${CONFIG.tolerance} pt) | ${scoreAgree}/${n} = **${scorePct}%** |
| Transcription accuracy (≥70% similarity) | ${transcribeWell}/${n} = **${transcribePct}%** |
| Both pass | ${bothPass}/${n} = **${bothPct}%** |

## By Handwriting Quality

| Quality | Score | Transcription |
|---|---|---|
${['good','medium','bad'].map(q => {
  const qr = results.filter(r => r.handwritingQuality === q);
  if (!qr.length) return null;
  const s = qr.filter(r => r.scorePass).length;
  const t = qr.filter(r => r.transcriptionPass).length;
  const qN = qr.length;
  return `| ${q} | ${s}/${qN} = ${Math.round(s/qN*100)}% | ${t}/${qN} = ${Math.round(t/qN*100)}% |`;
}).filter(Boolean).join('\n')}

## Case Details

| ID | Quality | Expected | Got | Score | Trans% | Pass |
|---|---|---|---|---|---|---|
${results.map(r => {
  const passIcon = r.bothPass ? '✓' : (r.error ? 'ERR' : '✗');
  return `| ${r.id} | ${r.handwritingQuality} | ${r.expectedScore} | ${r.modelScore ?? '?'} | ${r.scorePass ? '✓' : '✗'} | ${r.transcriptionSimilarity}% | ${passIcon} |`;
}).join('\n')}
`;

fs.writeFileSync(CONFIG.reportFile, md);
console.log(`Report saved:  ${CONFIG.reportFile}`);
